#!/bin/sh
# Build an X.509 seed corpus for mbedTLS, because the tree does not ship one.
#
# The case points its seeds at tests/data_files. In mbedtls-3.6.2 that directory does not
# exist: the certificates are generated by the test build, and the rest live in the
# `framework` submodule that a shallow clone skips. run-026 therefore fuzzed X.509 parsing
# with seeds=0 -- pure mutation against a format that is length-prefixed, tag-typed and
# nested. libFuzzer does not stumble into valid DER, so the campaign spent 6.3 million
# executions being rejected in the first few bytes of the outermost SEQUENCE.
#
# Same argument as pngsuite for libpng and the round-trip encoder for libwebp: when a format
# has structure, give the fuzzer something structurally valid to mutate away from.
#
# NOTE ON REPRODUCIBILITY: the key material differs on every fetch, so these seeds are not
# byte-identical between machines. Their SHAPE is, which is what a structure-aware corpus is
# for; a coverage figure that depended on one particular modulus would be the real problem.
set -eu
SRC="${1:-/b/mbedtls}"
OUT="$SRC/tests/data_files"
mkdir -p "$OUT"
cd "$OUT"

gen() { openssl "$@" >/dev/null 2>&1 || return 0; }

# RSA self-signed, PEM and DER -- mbedtls_x509_crt_parse takes either.
gen req -x509 -newkey rsa:2048 -keyout k_rsa.pem -out cert_rsa.pem -days 365 -nodes \
    -subj "/CN=hforge-seed-rsa/O=harness-forge/C=US"
gen x509 -in cert_rsa.pem -outform DER -out cert_rsa.der

# EC, a different key algorithm and a much smaller encoding.
gen req -x509 -newkey ec -pkeyopt ec_paramgen_curve:prime256v1 -keyout k_ec.pem \
    -out cert_ec.pem -days 365 -nodes -subj "/CN=hforge-seed-ec/O=harness-forge/C=US"
gen x509 -in cert_ec.pem -outform DER -out cert_ec.der

# Extensions: SAN, key usage, basic constraints. Each is a separate OID branch in the
# parser, and none of them is reachable from a certificate that carries no extensions.
cat > ext.cnf <<'CNF'
[req]
distinguished_name=dn
x509_extensions=v3
[dn]
[v3]
basicConstraints=critical,CA:TRUE,pathlen:1
keyUsage=critical,keyCertSign,cRLSign,digitalSignature
extendedKeyUsage=serverAuth,clientAuth
subjectAltName=DNS:a.example,DNS:*.b.example,IP:127.0.0.1,email:s@example
subjectKeyIdentifier=hash
CNF
gen req -x509 -newkey rsa:2048 -keyout k_ca.pem -out cert_ca.pem -days 365 -nodes \
    -subj "/CN=hforge-seed-ca/O=harness-forge/C=US" -config ext.cnf
gen x509 -in cert_ca.pem -outform DER -out cert_ca.der

# A concatenated PEM chain: the parser's loop over multiple certificates in one buffer.
cat cert_rsa.pem cert_ca.pem > chain.pem 2>/dev/null || true

# A CRL and a CSR: sibling entry points that share the ASN.1 core.
gen ca -gencrl -keyfile k_ca.pem -cert cert_ca.pem -out crl.pem -crldays 30 \
    -config /dev/null -subj "/CN=hforge-seed-ca"
gen req -new -key k_rsa.pem -out csr.pem -subj "/CN=hforge-seed-csr"

rm -f ext.cnf
echo "mbedtls: generated $(ls -1 "$OUT" 2>/dev/null | wc -l | tr -d ' ') X.509 seed file(s) into tests/data_files"
